/// Metadata about one flag, generated by ``FeatureFlags()``.
///
/// Powers the debug menu and lets tooling list every flag an app declares.
public struct FlagDefinition: Sendable, Hashable, Identifiable {
    public var id: String { key }

    /// The key used in remote config and overrides.
    public let key: String
    /// Taken from the property's `///` doc comment.
    public let description: String
    public let defaultValue: FlagRawValue
    /// Every allowed value, for `CaseIterable` flag types; otherwise `nil`.
    public let options: [FlagRawValue]?

    public init(key: String, description: String, defaultValue: FlagRawValue, options: [FlagRawValue]?) {
        self.key = key
        self.description = description
        self.defaultValue = defaultValue
        self.options = options
    }

    public static func options<Value: FlagValue>(for type: Value.Type) -> [FlagRawValue]? {
        nil
    }

    public static func options<Value: FlagValue & CaseIterable>(for type: Value.Type) -> [FlagRawValue]? {
        Value.allCases.map(\.flagRawValue)
    }
}

/// Reads typed values out of the resolved flag values.
///
/// A value of the wrong type (e.g. remote config sends `"yes"` for a `Bool`
/// flag) falls back to the default instead of crashing or silently coercing.
public struct FlagResolver: Sendable {
    public let values: [String: FlagRawValue]

    public init(values: [String: FlagRawValue] = [:]) {
        self.values = values
    }

    public func value<Value: FlagValue>(for key: String, default defaultValue: Value) -> Value {
        guard let raw = values[key], let value = Value(flagRawValue: raw) else {
            return defaultValue
        }
        return value
    }
}

/// A struct of flags. Don't conform to this by hand; apply ``FeatureFlags()``.
public protocol FeatureFlagContainer: Sendable {
    static var definitions: [FlagDefinition] { get }
    init(resolver: FlagResolver)
}
